import{Button}from'../../core/index.js';import{THREE,FACE}from'./geometry.js';import{spec}from'./dimensions.js';
/** Actual top-end U-cut tongue, with its native hinge retained at the front edge. */
export class NativeButton extends Button{
 constructor(shell){const hit=new THREE.Mesh(new THREE.PlaneGeometry(7.1,6.2),new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false}));hit.name='UnitV2 top native tongue input target';super({id:'user',label:'Top User button · input intent',mesh:hit,position:spec.user.position,quaternion:FACE.top,travel:spec.user.travelMm,longPressMs:0,meta:{role:'visual-control',visualMotion:'native-flexure',surfaceFace:'top',scope:'Press/release/cancel intent only;no boot,power,firmware,AI or network effects.',travelSource:'Photograph/native-hinge inference,not a material simulation or mechanical stop.'}});this.shell=shell;this.rest=shell.geometry.attributes.position.array.slice();this.norm=shell.geometry.attributes.normal.array.slice();this.weights=new Float32Array(this.rest.length/3);this.slopes=new Float32Array(this.weights.length);this.lastDepth=0;for(let i=0;i<this.weights.length;i++){const[x,y,z]=this.rest.slice(i*3,i*3+3);if(Math.abs(x)>3.64||y<22.1||z<.249||z>spec.user.hingeZ+.001)continue;const t=THREE.MathUtils.clamp((spec.user.hingeZ-z)/(spec.user.hingeZ-spec.user.freeZ),0,1);this.weights[i]=t*t*(3-2*t);this.slopes[i]=-6*t*(1-t)/(spec.user.hingeZ-spec.user.freeZ);}this.meta.deformedNativeVertices=this.weights.filter(w=>w>0).length;}
 update(dt){const changed=super.update(dt),depth=this.getActuationState().depthMm;if(depth===this.lastDepth)return changed;const p=this.shell.geometry.attributes.position,n=this.shell.geometry.attributes.normal;for(let i=0;i<this.weights.length;i++){if(!this.weights[i])continue;const k=i*3;p.setXYZ(i,this.rest[k],this.rest[k+1]-depth*this.weights[i],this.rest[k+2]);let nx=this.norm[k],ny=this.norm[k+1],nz=this.norm[k+2];if(depth){nz+=depth*this.slopes[i]*ny;const l=Math.hypot(nx,ny,nz);nx/=l;ny/=l;nz/=l;}n.setXYZ(i,nx,ny,nz);}p.needsUpdate=true;n.needsUpdate=true;this.shell.geometry.computeBoundingBox();this.shell.geometry.computeBoundingSphere();if(this.follower)this.follower.position.y=this.followerRest-depth;this.lastDepth=depth;return true;}
 dispose(){super.dispose();this.shell=null;this.rest=null;this.norm=null;this.weights=null;this.slopes=null;this.follower=null;}
}
